fast_pseudocode:
@triton.autotune(configs=[
    triton.Config({'BLOCK_COL': 32,  'BLOCK_RED': 64},  num_warps=4, num_stages=3),
    triton.Config({'BLOCK_COL': 32,  'BLOCK_RED': 64},  num_warps=4, num_stages=4),
    triton.Config({'BLOCK_COL': 64,  'BLOCK_RED': 64},  num_warps=4, num_stages=3),
    triton.Config({'BLOCK_COL': 128, 'BLOCK_RED': 32},  num_warps=4, num_stages=3),
    # ... num_stages=3 or 4 for all configs
])
def kernel(...):
    for r_start in range(0, N_RED, BLOCK_RED):
        tile = tl.load(ptrs, mask=mask, other=0.0, eviction_policy='evict_first')  # pipelined via cp.async
        acc += tl.sum(tile, axis=0)

